            expected_conn_removed.len()
        );
        let mut computed_conn_guids: Vec<&str> =
            computed_conn_removed.iter().map(|r| r.guid.as_str()).collect();
        computed_conn_guids.sort();
        let mut expected_conn_guids: Vec<&str> =
